SELECT event_type, SUM(CASE WHEN event_type = 'purchase' THEN duration_sec ELSE 0 END) AS purchase_duration_sec, COUNT_IF(event_type = 'purchase') AS purchase_events, BIT_AND(duration_sec) AS duration_sec_bit_and, COUNT_IF(event_type = 'add_to_cart') AS add_to_cart_events FROM web_events GROUP BY ROLLUP (event_type) HAVING SUM(CASE WHEN event_type = 'purchase' THEN duration_sec ELSE 0 END) > 0 ORDER BY duration_sec_bit_and;
